413: static SaveFileTextCallback saveFileText = NULL;    // SaveFileText callback function pointer"}, {"path": "src/rcore.c", "lines": [2101, 2211], "source_sha256": "25f60ed0e681e4565adb045870819d0eaed345aa975f8c609b73d8f691b6c42b", "text": "2101: // Load text data from file, returns a '\0' terminated string
2102: // NOTE: text chars array should be freed manually
2103: char *LoadFileText(const char *fileName)
2104: {
2105:     char *text = NULL;
2106: 
2107:     if (fileName != NULL)
2108:     {
2109:         if (loadFileText != NULL) return loadFileText(fileName);
2110: 
2111:         FILE *file = fopen(fileName, "rt");
2112: 
2113:         if (file != NULL)
2114:         {
2115:             // WARNING: When reading a file as 'text' file,
2116:             // text mode causes carriage return-linefeed translation...
2117:             // ...but using fseek() should return correct byte-offset
2118:             fseek(file, 0, SEEK_END);
2119:             unsigned int size = (unsigned int)ftell(file);
2120:             fseek(file, 0, SEEK_SET);
2121: 
2122:             if (size > 0)
2123:             {
2124:                 text = (char *)RL_CALLOC(size + 1, sizeof(char));
2125: 
2126:                 if (text != NULL)
2127:                 {
2128:                     unsigned int count = (unsigned int)fread(text, sizeof(char), size, file);
2129: 
2130:                     // WARNING: \r\n is converted to \n on reading, so,
2131:                     // read bytes count gets reduced by the number of lines
2132:                     if (count < size) text = (char *)RL_REALLOC(text, count + 1);
2133: 
2134:                     // Zero-terminate the string
2135:                     text[count] = '\0';
2136: 
2137:                     TRACELOG(LOG_INFO, "FILEIO: [%s] Text file loaded successfully", fileName);
2138:                 }
2139:                 else TRACELOG(LOG_WARNING, "FILEIO: [%s] Failed to allocated memory for file reading", fileName);
2140:             }
2141:             else TRACELOG(LOG_WARNING, "FILEIO: [%s] Failed to read text file", fileName);
2142: 
2143:             fclose(file);
2144:         }
2145:         else TRACELOG(LOG_WARNING, "FILEIO: [%s] Failed to open text file", fileName);
2146:     }
2147:     else TRACELOG(LOG_WARNING, "FILEIO: File name provided is not valid");
2148: 
2149:     return text;
2150: }
2151: 
2152: // Unload file text data allocated by LoadFileText()
2153: void UnloadFileText(char *text)
2154: {
2155:     RL_FREE(text);
2156: }
