2159: bool SaveFileText(const char *fileName, const char *text)
2160: {
2161:     bool result = false;
2162: 
2163:     if (fileName != NULL)
2164:     {
2165:         if (saveFileText != NULL) return saveFileText(fileName, text);
2166: 
2167:         FILE *file = fopen(fileName, "wt");
2168: 
2169:         if (file != NULL)
2170:         {
2171:             int count = fprintf(file, "%s", text);
2172: 
2173:             if (count < 0) TRACELOG(LOG_WARNING, "FILEIO: [%s] Failed to write text file", fileName);
2174:             else TRACELOG(LOG_INFO, "FILEIO: [%s] Text file saved successfully", fileName);
2175: 
2176:             int closed = fclose(file);
2177:             if (closed == 0) result = true;
2178:         }
2179:         else TRACELOG(LOG_WARNING, "FILEIO: [%s] Failed to open text file", fileName);
2180:     }
2181:     else TRACELOG(LOG_WARNING, "FILEIO: File name provided is not valid");
2182: 
2183:     return result;
2184: }
